1	package server
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"net/url"
9		"regexp"
10		"time"
11		"unicode/utf8"
12	)
13	
14	// leaseHeader carries the lease token on heartbeat and deregister requests.
15	const leaseHeader = "X-Meshcore-Lease"
16	
17	// namePattern constrains service and instance names: 1-64 ASCII letters,
18	// digits, dots, underscores or hyphens.
19	var namePattern = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)
20	
21	func validName(s string) bool { return namePattern.MatchString(s) }
22	
23	type healthPolicyRequest struct {
24		FailureThreshold *int `json:"failureThreshold"`
25		SuccessThreshold *int `json:"successThreshold"`
26	}
27	
28	type registerRequest struct {
29		Endpoint     string               `json:"endpoint"`
30		Version      string               `json:"version"`
31		Zone         string               `json:"zone"`
32		Weight       int                  `json:"weight"`
33		TTLSeconds   int                  `json:"ttlSeconds"`
34		Metadata     map[string]string    `json:"metadata"`
35		HealthPolicy *healthPolicyRequest `json:"healthPolicy"`
36	}
37	
38	func (r *registerRequest) valid() bool {
39		if r.Endpoint == "" || r.Version == "" || r.Zone == "" {
40			return false
41		}
42		if r.Weight < 1 || r.Weight > 100 || r.TTLSeconds < 1 || r.TTLSeconds > 300 {
43			return false
44		}
45		for k, v := range r.Metadata {
46			if k == "" || v == "" {
47				return false
48			}
49		}
50		if r.HealthPolicy != nil {
51			p := r.HealthPolicy
52			if p.FailureThreshold == nil || p.SuccessThreshold == nil {
53				return false
54			}
55			if *p.FailureThreshold < 1 || *p.FailureThreshold > 10 ||
56				*p.SuccessThreshold < 1 || *p.SuccessThreshold > 10 {
57				return false
58			}
59		}
60		return true
61	}
62	
63	// instanceView is the public representation of a registered instance. The
64	// lease token is deliberately excluded; it only appears in registerResponse.
65	type instanceView struct {
66		Service      string            `json:"service"`
67		Instance     string            `json:"instance"`
68		Endpoint     string            `json:"endpoint"`
69		Version      string            `json:"version"`
70		Zone         string            `json:"zone"`
71		Weight       int               `json:"weight"`
72		TTLSeconds   int               `json:"ttlSeconds"`
73		Metadata     map[string]string `json:"metadata"`
74		ExpiresAt    string            `json:"expiresAt"`
75		HealthStatus string            `json:"healthStatus"`
76	}
77	
78	func viewOf(inst instance) instanceView {
79		return instanceView{
80			Service:      inst.Service,
81			Instance:     inst.Instance,
82			Endpoint:     inst.Endpoint,
83			Version:      inst.Version,
84			Zone:         inst.Zone,
85			Weight:       inst.Weight,
86			TTLSeconds:   inst.TTLSeconds,
87			Metadata:     inst.Metadata,
88			ExpiresAt:    inst.expiresAt.UTC().Format(time.RFC3339),
89			HealthStatus: inst.healthStatus(),
90		}
91	}
92	
93	type registerResponse struct {
94		instanceView
95		LeaseToken string `json:"leaseToken"`
96	}
97	
98	type discoveryResponse struct {
99		Service   string         `json:"service"`
100		Instances []instanceView `json:"instances"`
101	}
102	
103	type resolveResponse struct {
104		Service  string       `json:"service"`
105		Key      string       `json:"key"`
106		Instance instanceView `json:"instance"`
107	}
108	
109	func writeJSON(w http.ResponseWriter, status int, v any) {
110		w.Header().Set("Content-Type", "application/json; charset=utf-8")
111		w.WriteHeader(status)
112		_ = json.NewEncoder(w).Encode(v)
113	}
114	
115	func writeError(w http.ResponseWriter, status int, code string) {
116		writeJSON(w, status, map[string]any{"error": map[string]string{"code": code}})
117	}
118	
119	// handleInstance serves /v1/services/{service}/instances/{instance}.
120	func (s *server) handleInstance(w http.ResponseWriter, r *http.Request) {
121		switch r.Method {
122		case http.MethodPut:
123			s.register(w, r)
124		case http.MethodDelete:
125			s.deregister(w, r)
126		default:
127			w.Header().Set("Allow", "PUT, DELETE")
128			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
129		}
130	}
131	
132	func (s *server) register(w http.ResponseWriter, r *http.Request) {
133		service, name := r.PathValue("service"), r.PathValue("instance")
134		if !validName(service) || !validName(name) {
135			writeError(w, http.StatusBadRequest, "validation_error")
136			return
137		}
138		var req registerRequest
139		dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
140		dec.DisallowUnknownFields()
141		if err := dec.Decode(&req); err != nil || dec.Decode(&struct{}{}) != io.EOF || !req.valid() {
142			writeError(w, http.StatusBadRequest, "validation_error")
143			return
144		}
145		metadata := make(map[string]string, len(req.Metadata))
146		for k, v := range req.Metadata {
147			metadata[k] = v
148		}
149		inst := &instance{
150			Service:    service,
151			Instance:   name,
152			Endpoint:   req.Endpoint,
153			Version:    req.Version,
154			Zone:       req.Zone,
155			Weight:     req.Weight,
156			TTLSeconds: req.TTLSeconds,
157			Metadata:   metadata,
158		}
159		if p := req.HealthPolicy; p != nil {
160			inst.health = healthState{
161				configured:       true,
162				failureThreshold: *p.FailureThreshold,
163				successThreshold: *p.SuccessThreshold,
164				status:           healthHealthy,
165			}
166		}
167		stored, overwritten := s.registry.register(inst, s.now())
168		status := http.StatusCreated
169		if overwritten {
170			status = http.StatusOK
171		}
172		writeJSON(w, status, registerResponse{instanceView: viewOf(stored), LeaseToken: stored.token})
173	}
174	
175	func (s *server) deregister(w http.ResponseWriter, r *http.Request) {
176		service, name := r.PathValue("service"), r.PathValue("instance")
177		if !validName(service) || !validName(name) {
178			writeError(w, http.StatusBadRequest, "validation_error")
179			return
180		}
181		err := s.registry.deregister(service, name, r.Header.Get(leaseHeader), s.now())
182		writeLeaseResult(w, err)
183	}
184	
185	// handleHeartbeat serves /v1/services/{service}/instances/{instance}/heartbeat.
186	func (s *server) handleHeartbeat(w http.ResponseWriter, r *http.Request) {
187		if r.Method != http.MethodPost {
188			w.Header().Set("Allow", http.MethodPost)
189			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
190			return
191		}
192		service, name := r.PathValue("service"), r.PathValue("instance")
193		if !validName(service) || !validName(name) {
194			writeError(w, http.StatusBadRequest, "validation_error")
195			return
196		}
197		err := s.registry.renew(service, name, r.Header.Get(leaseHeader), s.now())
198		writeLeaseResult(w, err)
199	}
