201	func writeLeaseResult(w http.ResponseWriter, err error) {
202		switch {
203		case err == nil:
204			w.WriteHeader(http.StatusNoContent)
205		case errors.Is(err, errNotFound):
206			writeError(w, http.StatusNotFound, "instance_not_found")
207		case errors.Is(err, errLeaseConflict):
208			writeError(w, http.StatusConflict, "lease_conflict")
209		default:
210			writeError(w, http.StatusInternalServerError, "internal_error")
211		}
212	}
213	
214	// healthReportRequest is the body of a health report. Pointers distinguish
215	// an absent field from a zero value; both fields are required.
216	type healthReportRequest struct {
217		Sequence *int64  `json:"sequence"`
218		Status   *string `json:"status"`
219	}
220	
221	// handleHealth serves /v1/services/{service}/instances/{instance}/health.
222	// Existence, lease token and policy checks run inside the registry under one
223	// lock so concurrent reports, heartbeats and deregistrations stay atomic;
224	// the body is decoded up front but its validation error is only surfaced
225	// after those checks, matching the documented error precedence.
226	func (s *server) handleHealth(w http.ResponseWriter, r *http.Request) {
227		if r.Method != http.MethodPost {
228			w.Header().Set("Allow", http.MethodPost)
229			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
230			return
231		}
232		service, name := r.PathValue("service"), r.PathValue("instance")
233		if !validName(service) || !validName(name) {
234			writeError(w, http.StatusBadRequest, "validation_error")
235			return
236		}
237		var req healthReportRequest
238		dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
239		dec.DisallowUnknownFields()
240		bodyOK := dec.Decode(&req) == nil && dec.Decode(&struct{}{}) == io.EOF &&
241			req.Sequence != nil && *req.Sequence >= 0 &&
242			req.Status != nil && (*req.Status == "pass" || *req.Status == "fail")
243		var seq int64
244		pass := false
245		if bodyOK {
246			seq = *req.Sequence
247			pass = *req.Status == "pass"
248		}
249		err := s.registry.reportHealth(service, name, r.Header.Get(leaseHeader), bodyOK, seq, pass, s.now())
250		switch {
251		case err == nil:
252			w.WriteHeader(http.StatusNoContent)
253		case errors.Is(err, errNotFound):
254			writeError(w, http.StatusNotFound, "instance_not_found")
255		case errors.Is(err, errLeaseConflict):
256			writeError(w, http.StatusConflict, "lease_conflict")
257		case errors.Is(err, errHealthDisabled):
258			writeError(w, http.StatusConflict, "health_check_disabled")
259		case errors.Is(err, errInvalidHealthReport):
260			writeError(w, http.StatusBadRequest, "validation_error")
261		case errors.Is(err, errHealthReportConflict):
262			writeError(w, http.StatusConflict, "health_report_conflict")
263		case errors.Is(err, errStaleHealthReport):
264			writeError(w, http.StatusConflict, "stale_health_report")
265		default:
266			writeError(w, http.StatusInternalServerError, "internal_error")
267		}
268	}
269	
270	// handleDiscovery serves /v1/discovery/{service}.
271	func (s *server) handleDiscovery(w http.ResponseWriter, r *http.Request) {
272		if r.Method != http.MethodGet {
273			w.Header().Set("Allow", http.MethodGet)
274			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
275			return
276		}
277		service := r.PathValue("service")
278		if !validName(service) {
279			writeError(w, http.StatusBadRequest, "validation_error")
280			return
281		}
282		query, err := url.ParseQuery(r.URL.RawQuery)
283		if err != nil {
284			writeError(w, http.StatusBadRequest, "validation_error")
285			return
286		}
287		var version, zone string
288		for key, values := range query {
289			if (key != "version" && key != "zone") || len(values) != 1 || values[0] == "" {
290				writeError(w, http.StatusBadRequest, "validation_error")
291				return
292			}
293			if key == "version" {
294				version = values[0]
295			} else {
296				zone = values[0]
297			}
298		}
299		instances := s.registry.snapshot(service, version, zone, s.now())
300		views := make([]instanceView, 0, len(instances))
301		for _, inst := range instances {
302			views = append(views, viewOf(inst))
303		}
304		writeJSON(w, http.StatusOK, discoveryResponse{Service: service, Instances: views})
305	}
306	
307	// maxKeyBytes bounds the URL-decoded routing key accepted by handleResolve.
308	const maxKeyBytes = 256
309	
310	// handleResolve serves /v1/resolve/{service}: it maps the caller's routing
311	// key onto a single live instance via consistent hashing. The selection is
312	// computed from the current snapshot only; it never creates or extends a
313	// lease.
314	func (s *server) handleResolve(w http.ResponseWriter, r *http.Request) {
315		if r.Method != http.MethodGet {
316			w.Header().Set("Allow", http.MethodGet)
317			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
318			return
319		}
320		service := r.PathValue("service")
321		if !validName(service) {
322			writeError(w, http.StatusBadRequest, "validation_error")
323			return
324		}
325		query, err := url.ParseQuery(r.URL.RawQuery)
326		if err != nil {
327			writeError(w, http.StatusBadRequest, "validation_error")
328			return
329		}
330		var key, version, zone string
331		for param, values := range query {
332			if len(values) != 1 || values[0] == "" {
333				writeError(w, http.StatusBadRequest, "validation_error")
334				return
335			}
336			switch param {
337			case "key":
338				key = values[0]
339			case "version":
340				version = values[0]
341			case "zone":
342				zone = values[0]
343			default:
344				writeError(w, http.StatusBadRequest, "validation_error")
345				return
346			}
347		}
348		if key == "" || len(key) > maxKeyBytes || !utf8.ValidString(key) {
349			writeError(w, http.StatusBadRequest, "validation_error")
350			return
351		}
352		instances := s.registry.snapshot(service, version, zone, s.now())
353		chosen, ok := selectInstance(key, instances)
354		if !ok {
355			writeError(w, http.StatusServiceUnavailable, "no_available_instance")
356			return
357		}
358		writeJSON(w, http.StatusOK, resolveResponse{Service: service, Key: key, Instance: viewOf(chosen)})
359	}
