30	func errorCode(t *testing.T, rec *httptest.ResponseRecorder) string {
31		t.Helper()
32		var payload struct {
33			Error struct {
34				Code string `json:"code"`
35			} `json:"error"`
36		}
37		if err := json.Unmarshal(rec.Body.Bytes(), &payload); err != nil {
38			t.Fatalf("error response is not JSON: %v (body %q)", err, rec.Body.String())
39		}
40		return payload.Error.Code
