	}
	for key, owner := range afterRemoval {
		now := resolveOK(t, h, "/v1/resolve/svc?key="+key).Instance.Instance
		if now != owner && now != "n5" {
			t.Fatalf("key %q migrated from %q to %q on addition; only the new instance may steal", key, owner, now)
		}
	}
