		writeError(w, http.StatusInternalServerError, "internal_error")
		return
	}
	writeJSON(w, http.StatusCreated, acquireResponse{
		Service:     service,
		Key:         *req.Key,
		Instance:    viewOf(inst),
		PermitToken: token,
