	mustRegister(t, h, "svc", "i1", registerBodyWithQuota("http://a:1", "v1", "z1", 10, 60, 1))
	mustRegister(t, h, "svc", "i2", registerBody("http://b:1", "v2", "z2", 10, 60))

	acquireOK(t, h, "svc", `{"key":"k","permitTTLSeconds":60,"version":"v1","zone":"z1"}`)
