	acquireOK(t, h, "svc", `{"key":"k","permitTTLSeconds":60}`)
	if rec := acquire(t, h, "svc", `{"key":"k","permitTTLSeconds":60}`); rec.Code != http.StatusTooManyRequests {
		t.Fatalf("acquire beyond new quota = %d, want 429", rec.Code)
	}
}

